package dev.qperiapt.continuity.android.tests;

import dev.qperiapt.continuity.android.*;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermissions;
import static dev.qperiapt.continuity.android.tests.EnrollmentProbe.*;

/** Registry keys and databases are generated by the consuming endpoint, never copied from the issuer. */
public final class AuthorityProbe {
    private AuthorityProbe() { }
    static Path directory(Path installation) { return installation.resolveSibling(installation.getFileName() + "-authority"); }
    private static AccountAuthorityTrust trust(Path inputs) throws Exception {
        return new AccountAuthorityTrust(new Ids.AccountAuthority(read(inputs, "authority-id")), read(inputs, "family"),
            read(inputs, "witness-id"), read(inputs, "witness-public"));
    }
    static ContinuityAccountAuthority open(Path inputs, Path installation) throws Exception {
        ContinuityAccountAuthority registry = ContinuityAccountAuthority.prepareOpen(directory(installation).toString(), trust(inputs));
        try { registry.finishOpen(); return registry; }
        catch (Throwable failure) {
            try { registry.close(); } catch (Throwable cleanup) { failure.addSuppressed(cleanup); }
            throw failure;
        }
    }
    static AccountAuthorityCheckpoint expected(Path inputs) throws Exception {
        byte[] bytes = read(inputs, "authority-checkpoint"); require(bytes.length == 72, "authority checkpoint width");
        ByteBuffer wire = ByteBuffer.wrap(bytes); byte[] application = new byte[32], account = new byte[32];
        wire.get(application); Counter64 revision = counter(wire); wire.get(account);
        return new AccountAuthorityCheckpoint(new Ids.ApplicationAccount(application), revision, new Ids.Account(account));
    }
    private static byte[] encoded(AccountAuthorityCheckpoint checkpoint) {
        return ByteBuffer.allocate(72).put(checkpoint.application().encoded())
            .putLong(Long.parseUnsignedLong(checkpoint.revision().toString())).put(checkpoint.account().encoded()).array();
    }
    public static void main(String[] args) throws Exception {
        if (args.length != 5) throw new IllegalArgumentException("inputs installation profile mode result");
        Path inputs = Path.of(args[0]), installation = Path.of(args[1]), output = Path.of(args[4]);
        require(args[2].equals("fixed") || args[2].equals("recoverable"), "profile");
        Ids.ApplicationAccount application = new Ids.ApplicationAccount(read(inputs, "authority-application"));
        if (args[3].equals("authority-create")) {
            Path directory = directory(installation);
            Files.createDirectory(directory, PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));
            ContinuityAccountAuthority.provisionWrappingKey(directory.toString());
            try (ContinuityAccountAuthority registry = ContinuityAccountAuthority.prepareCreate(directory.toString(), trust(inputs))) {
                registry.finishOpen();
                failed(201, () -> registry.checkpoint(application));
                AccountPin pin = new AccountPin(read(inputs, "trusted-account"), read(inputs, "enrollment-root"), read(inputs, "family"),
                    counter(ByteBuffer.wrap(read(inputs, "trusted-roster-version"))), read(inputs, "trusted-roster-digest"));
                byte[] certificate = read(inputs, "grant-certificate"), roster = read(inputs, "grant-roster");
                byte[] corrupt = certificate.clone(); corrupt[corrupt.length - 1] ^= 1;
                failed(102, () -> registry.associate(application, pin, corrupt, roster));
                failed(201, () -> registry.checkpoint(application));
                AccountAuthorityCheckpoint checkpoint = registry.associate(application, pin, certificate, roster);
                require(checkpoint.application().equals(application) && checkpoint.revision().equals(new Counter64("1"))
                    && checkpoint.account().equals(new Ids.Account(read(inputs, "trusted-account"))), "approved association");
                require(registry.associate(application, pin, certificate, roster).equals(checkpoint), "association replay changed revision");
                require(registry.checkpoint(application).equals(checkpoint), "association readback");
                failed(211, () -> ContinuityAccountAuthority.provisionWrappingKey(directory.toString()));
                publish(output, encoded(checkpoint));
            }
        } else if (args[3].equals("authority-reopen")) {
            try (ContinuityAccountAuthority registry = open(inputs, installation)) {
                AccountAuthorityCheckpoint expected = expected(inputs);
                require(registry.checkpoint(application).equals(expected), "original association changed after reopen");
                publish(output, encoded(expected));
            }
        } else throw new IllegalArgumentException("authority operation");
        System.out.println(args[2] + ":" + args[3] + ":passed");
    }
}
